package com.argument.finalreview;

import com.argument.adjudication.*;
import com.argument.common.exception.*;
import com.argument.integration.UnifiedVersionIdentity;
import com.argument.membera.service.SegmentationService;
import com.argument.segmentationtrial.*;
import com.argument.version.*;
import com.argument.version.port.AnnotationDependencies;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Component;
import static com.argument.adjudication.AdjudicationService.require;

/** Explicit D-branch certificate: real canonical inputs, never a production certificate. */
@Component @Profile("(local | test) & !prod")
public class IntegratedTrialEvidence {
    private final AnnotationDependencies data;private final AdjudicationService adjudication;private final AdjudicationRepository sessions;private final AdjudicationDependencies dependencies;
    private final SegmentationService independent;private final SegmentationTrialService segmentation;private final SegmentationTrialRepository calculations;private final SegmentationAgreement algorithm;private final UnifiedVersionIdentity identity;private final ObjectMapper mapper;
    public IntegratedTrialEvidence(AnnotationDependencies data,AdjudicationService adjudication,AdjudicationRepository sessions,AdjudicationDependencies dependencies,SegmentationService independent,SegmentationTrialService segmentation,SegmentationTrialRepository calculations,SegmentationAgreement algorithm,UnifiedVersionIdentity identity,ObjectMapper mapper){this.data=data;this.adjudication=adjudication;this.sessions=sessions;this.dependencies=dependencies;this.independent=independent;this.segmentation=segmentation;this.calculations=calculations;this.algorithm=algorithm;this.identity=identity;this.mapper=mapper;}
    public ObjectNode assess(ObjectNode snapshot,ObjectNode session){
        var result=mapper.createObjectNode().put("ready",false).put("blocking",false).put("mode","D_BRANCH_TRIAL");String caseId=session.path("taskDocumentId").asText();
        if(data.find("segmentationSubmission","taskDocumentId",caseId).isEmpty())return result.put("message","历史预置或非独立审核输入不具备真实试行凭证资格");
        try{
            result.put("blocking",true);var doc=data.read("taskDocument",caseId);var version=snapshot.path("version");var sources=adjudication.snapshots(session);var owners=new HashSet<String>();String checkpoint=null;
            require(sources.size()>=Math.max(2,doc.path("requiredAnnotators").asInt()),ErrorCode.SOURCE_INCOMPLETE,"未收齐真实独立来源版本");
            for(var source:sources){var v=source.path("version");require(owners.add(v.path("submittedById").asText()),ErrorCode.SOURCE_INCOMPLETE,"来源必须来自不同标注账号");for(String field:List.of("documentTextVersionId","annotationScopeId","guideVersionId"))require(version.path(field).equals(v.path(field)),ErrorCode.SOURCE_INCOMPLETE,"来源与最终版基准不同");String cp=v.path("segmentationCheckpointId").asText();if(checkpoint==null)checkpoint=cp;else require(checkpoint.equals(cp),ErrorCode.SOURCE_INCOMPLETE,"来源关口不一致");}
            var cp=data.read("checkpoint",checkpoint);require(cp.path("taskDocumentId").asText().equals(caseId)&&"CONFIRMED".equals(cp.path("status").asText())&&cp.hasNonNull("calculationId"),ErrorCode.SOURCE_INCOMPLETE,"统一关口缺少真实计算来源");
            var calculation=calculations.get("CALCULATION",cp.path("calculationId").asText());for(String field:List.of("documentTextVersionId","annotationScopeId"))require(cp.path(field).equals(version.path(field))&&calculation.path(field).equals(version.path(field))&&doc.path(field).equals(version.path(field)),ErrorCode.SOURCE_INCOMPLETE,"关口、计算与最终版基准不同");require(calculation.path("passed").asBoolean()&&">".equals(calculation.path("thresholdOperator").asText())&&Double.compare(calculation.path("threshold").asDouble(),0.8)==0,ErrorCode.SOURCE_INCOMPLETE,"计算记录阈值或通过标志不符");var inputs=independent.acceptedInputs(caseId);require(inputs.size()>=Math.max(2,doc.path("requiredAnnotators").asInt())&&calculation.path("inputDigest").asText().equals(VersionJson.sha256(inputs.toString())),ErrorCode.SOURCE_INCOMPLETE,"切割输入或有效成员已变化");
            require(calculation.path("taskDocumentId").asText().equals(caseId)&&algorithm.code().equals(calculation.path("algorithmCode").asText())&&algorithm.version().equals(calculation.path("algorithmVersion").asText()),ErrorCode.SOURCE_INCOMPLETE,"计算范围或算法版本不匹配");
            var sets=new ArrayList<Set<Integer>>();var inputIds=mapper.createArrayNode();for(var input:inputs){sets.add(segmentation.boundaries(doc,input.path("boundaries")));inputIds.add(input.path("id").asText());}
            require(inputs.stream().map(i->i.path("submittedById").asText()).collect(java.util.stream.Collectors.toSet()).containsAll(owners),ErrorCode.SOURCE_INCOMPLETE,"固定来源标注员已失去有效切割资格");var recomputed=algorithm.calculate(sets);require(recomputed.passed()&&recomputed.numerator().equals(calculation.path("scoreNumerator").asText())&&recomputed.denominator().equals(calculation.path("scoreDenominator").asText())&&Double.compare(recomputed.score(),calculation.path("aggregateScore").asDouble())==0&&cp.path("agreementScore").equals(calculation.path("aggregateScore"))&&inputIds.equals(calculation.path("inputSubmissionIds"))&&inputIds.equals(cp.path("sourceSubmissionIds")),ErrorCode.SOURCE_INCOMPLETE,"切割计算复算或固定输入覆盖失败");segmentation.boundaries(doc,cp.path("unifiedBoundaries"));
            var text=data.read("text",version.path("documentTextVersionId").asText());require(text.path("contentSha256").equals(cp.path("textSha256"))&&text.path("contentSha256").equals(calculation.path("textSha256"))&&cp.path("boundaryHash").asText().equals(VersionJson.sha256(cp.path("unifiedBoundaries").toString())),ErrorCode.SOURCE_INCOMPLETE,"文本或统一边界摘要不匹配");
            var mapping=data.read("adjudicationMapping",session.path("id").asText());require(!mapping.path("fixture").asBoolean(true)&&mapping.hasNonNull("unifiedSnapshotId"),ErrorCode.SOURCE_INCOMPLETE,"缺少真实统一命题快照");var unified=data.read("unifiedSnapshot",mapping.path("unifiedSnapshotId").asText());require(unified.path("sessionId").equals(session.path("id"))&&unified.path("sourceVersionIds").equals(session.path("sourceVersionIds")),ErrorCode.SOURCE_INCOMPLETE,"统一映射不属于固定会话");
            var relationItems=sessions.items(session.path("id").asText(),"RELATION");var current=new ArrayList<>(adjudication.current(sessions.items(session.path("id").asText(),"PROPOSITION"),sessions.decisions(session.path("id").asText())));current.addAll(adjudication.current(relationItems,sessions.decisions(session.path("id").asText())));dependencies.validateRelations(session,sources,relationItems,current);dependencies.checkExperts(session);
            var experts=mapper.createArrayNode();for(var review:data.find("expertReview","sessionId",session.path("id").asText())){var member=data.read("member",review.path("expertTaskMemberId").asText());var actor=identity.actor(review.path("expertUserId").asText());require(actor.role("EXPERT")&&actor.permission("EXPERT_REVIEW")&&"ACTIVE".equals(member.path("status").asText())&&"EXPERT".equals(member.path("memberRole").asText())&&member.path("userId").equals(review.path("expertUserId"))&&member.path("taskId").equals(doc.path("taskId")),ErrorCode.EXPERT_NOT_ASSIGNED,"专家账号或原指派成员已失效");experts.add(review);for(var issue:data.find("expertIssue","expertReviewId",review.path("id").asText()))experts.add(issue);}
            var proof=result.putObject("proof");proof.put("validatorVersion","integrated-real-inputs-trial-1").put("contentDigest",FinalReviewService.contentDigest(snapshot)).put("decisionDigest",snapshot.path("decisionDigest").asText()).put("guideVersionId",version.path("guideVersionId").asText()).put("textSha256",text.path("contentSha256").asText()).put("documentTextVersionId",version.path("documentTextVersionId").asText()).put("annotationScopeId",version.path("annotationScopeId").asText()).put("guideDigest",VersionJson.canonicalHash(data.read("guideVersion",version.path("guideVersionId").asText()))).put("definitionDigest",VersionJson.canonicalHash(mapper.valueToTree(List.of(data.find("label","guideVersionId",version.path("guideVersionId").asText()),data.find("relationDefinition","guideVersionId",version.path("guideVersionId").asText()))))).put("scopeDigest",VersionJson.canonicalHash(data.read("scope",version.path("annotationScopeId").asText()))).put("checkpointDigest",VersionJson.canonicalHash(cp)).put("calculationDigest",VersionJson.canonicalHash(calculation)).put("inputDigest",VersionJson.canonicalHash(mapper.valueToTree(inputs))).put("mappingDigest",VersionJson.canonicalHash(mapping)).put("unifiedDigest",VersionJson.canonicalHash(unified)).put("sourceDigest",VersionJson.canonicalHash(mapper.valueToTree(sources))).put("expertDigest",VersionJson.canonicalHash(experts));
            return result.put("ready",true).put("blocking",false).put("message","真实独立输入已复算；命题映射、当前关系决定与专家资格已核验，可按授权方案试行审查及入库");
        }catch(BusinessException e){return result.put("message",e.getMessage());}
    }
}
